sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 shadows;
layout(color) uniform half4 midtones;
layout(color) uniform half4 highlights;
uniform float amount;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float l = luma(base);
    float lows = 1.0 - smoothstep(0.0, 0.5, l);
    float highs = smoothstep(0.5, 1.0, l);
    float3 shift = lows * (float3(shadows.rgb) - 0.5) + (1.0 - lows - highs) * (float3(midtones.rgb) - 0.5) + highs * (float3(highlights.rgb) - 0.5);
    float3 rgb = base + shift * clamp(amount, 0.0, 1.0);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
